{"command":"cd /Users/log/.local/share/opencode/tool-output && python3 - <<'EOF'
import json, urllib.request
UA = {"ANDROID":"com.google.android.youtube/19.09.37 (Linux; U; Android 11) gzip",
      "MWEB":"Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.0 Mobile/15E148 Safari/604.1",
      "TVHTML5":"Mozilla/5.0 (ChromiumStylePlatform) Cobalt/Version"}
for client in ["ANDROID","MWEB","TVHTML5"]:
    body = json.dumps({"context":{"client":{"clientName":client,"clientVersion":{"ANDROID":"19.09.37","MWEB":"2.20240304.00.00","TVHTML5":"7.20240304.00.00"}[client],"hl":"en"}},"videoId":"85vCxsifdlQ"}).encode()
    req = urllib.request.Request("https://www.youtube.com/youtubei/v1/player?prettyPrint=false", data=body,
        headers={"User-Agent":UA[client],"Content-Type":"application/json"})
    try:
        r = json.loads(urllib.request.urlopen(req, timeout=30).read())
        sb = r.get("storyboards") or (r.get("streamingData") or {}).get("storyboards")
        print(client, r.get("videoDetails",{}).get("title"), "| storyboards:", bool(sb))
        if sb: print(json.dumps(sb)[:800])
    except Exception as e:
        print(client, "ERR", e)
EOF"}

