const vids = ["85vCxsifdlQ","o-q5iROzPNY","J1pOTTcdRO8","P_znsXp0j5o","5gYL9znVmGs"];
const out = [];
for (const v of vids) {
  try {
    const tab = await tools.browser.tabs.open(`https://www.youtube.com/watch?v=${v}&hl=en`, {focus:false});
    await new Promise(r => setTimeout(r, 3500));
    const ev = await tools.browser.evaluate({tabID: tab.id, expression: "JSON.stringify({t: ytInitialPlayerResponse?.videoDetails?.title, sb: ytInitialPlayerResponse?.storyboards || null})"});
    out.push({v, ev});
    await tools.browser.tabs.close({tabID: tab.id});
  } catch (e) { out.push({v, err: String(e)}); }
}
return out

