import re, base64, sys, os, json
from PIL import Image
import numpy as np
import io

def mhtml_images(path):
    raw = open(path, "rb").read().decode("utf-8", "ignore")
    imgs = []
    # mhtml parts
    for m in re.finditer(r"Content-Type: image/jpeg.*?Content-Transfer-Encoding: base64\r?\n\r?\n(.*?)(?:------=|$)", raw, re.S):
        b64 = m.group(1).replace("\r", "").replace("\n", "")
        try:
            imgs.append(Image.open(io.BytesIO(base64.b64decode(b64))).convert("RGB"))
        except Exception as e:
            pass
    return imgs

def slice_sprite(im, tw=160, th=90):
    w, h = im.size
    # find thumb size that divides evenly
    for cand in [(160,90),(80,45),(320,180),(640,360),(128,72)]:
        tw, th = cand
        if w % tw == 0 and h % th == 0 and (w//tw)*(h//th) > 1:
            break
    cols, rows = w//tw, h//th
    frames = []
    for r in range(rows):
        for c in range(cols):
            fr = im.crop((c*tw, r*th, (c+1)*tw, (r+1)*th))
            frames.append(fr)
    return frames

def frame_stats(fr):
    a = np.asarray(fr.resize((32,18))).astype(float)
    m = a.mean(axis=(0,1))
    return m

def process(vid):
    p = f"sb_{vid}.mhtml"
    if not os.path.exists(p):
        return None
    ims = mhtml_images(p)
    allf = []
    for im in ims:
        allf += slice_sprite(im)
    stats = np.array([frame_stats(f) for f in allf])
    return stats

if __name__ == "__main__":
    vids = json.loads(sys.argv[1])
    out = {}
    for name, vid in vids:
        s = process(vid)
        if s is None:
            print(name, vid, "MISSING")
            continue
        out[name] = s.round(1).tolist()
        print(f"{name:28s} {vid} frames={len(s)} mean={s.mean(axis=0).round(0)}")
    json.dump(out, open("trailer_stats.json","w"))

