import re, sys, os, json, io
from PIL import Image
import numpy as np

def mhtml_images(path):
    raw = open(path, "rb").read()
    boundary = re.search(rb'boundary="([^"]+)"', raw).group(1)
    parts = raw.split(b"--" + boundary)
    imgs = []
    for p in parts:
        if b"image/" in p[:400]:
            i = p.find(b"\r\n\r\n")
            if i == -1: continue
            data = p[i+4:]
            try:
                imgs.append(Image.open(io.BytesIO(data)).convert("RGB"))
            except Exception as e:
                pass
    return imgs

def slice_sprite(im):
    w, h = im.size
    for cand in [(160,90),(80,45),(320,180),(640,360),(128,72)]:
        tw, th = cand
        if w % tw == 0 and h % th == 0 and (w//tw)*(h//th) >= 1:
            break
    cols, rows = max(1,w//tw), max(1,h//th)
    frames = []
    for r in range(rows):
        for c in range(cols):
            frames.append(im.crop((c*tw, r*th, (c+1)*tw, (r+1)*th)))
    return frames

def frame_stats(fr):
    a = np.asarray(fr.resize((32,18))).astype(float)
    return a.mean(axis=(0,1))

def process(vid):
    p = f"sb_{vid}.mhtml"
    if not os.path.exists(p): return None
    allf = []
    for im in mhtml_images(p):
        allf += slice_sprite(im)
    if not allf: return None
    return np.array([frame_stats(f) for f in allf])

if __name__ == "__main__":
    vids = json.loads(sys.argv[1])
    out = {}
    for name, vid in vids:
        s = process(vid)
        if s is None:
            print(name, vid, "MISSING"); continue
        out[name] = s.round(2).tolist()
        print(f"{name:14s} frames={len(s):3d} meanRGB={s.mean(axis=0).round(0)}")
    json.dump(out, open("trailer_stats.json","w"))
    print("saved trailer_stats.json")

